import sailpoint.object.Identity;

Identity oldId = null;
Identity newId = null;
if (event != null) {
    try { oldId = (Identity) event.getOldObject(); } catch (Exception e) { }
    try { newId = (Identity) event.getNewObject(); } catch (Exception e) { }
}
if (newId == null && identityName != null) {
    newId = context.getObjectByName(Identity.class, identityName);
}

workflow.put("oldStatus", oldId == null ? null : (String) oldId.getAttribute("status"));
if (newId != null) {
    workflow.put("newStatus",      (String) newId.getAttribute("status"));
    workflow.put("displayName",    newId.getDisplayName());
    workflow.put("startDate",      (String) newId.getAttribute("startDate"));
    workflow.put("endDate",        (String) newId.getAttribute("endDate"));
    workflow.put("jobDescription", (String) newId.getAttribute("jobDescription"));
    Identity mgr = newId.getManager();
    workflow.put("managerName", mgr == null ? null : mgr.getDisplayName());
}

if (!"Terminated".equals(oldStatus) || !"Active".equals(newStatus)) return false;
sailpoint.object.Identity id = context.getObjectByName(sailpoint.object.Identity.class, identityName);
Object ed = (id == null) ? null : id.getAttribute("emergencyDisable");
return ed == null || !"true".equalsIgnoreCase(ed.toString().trim());
